// Per-card header photos keyed by card id — { [key]: { src, x, y, scale } }. Updated by applyPP.
let CARD_MEDIA = (_PP.CARD_MEDIA && typeof _PP.CARD_MEDIA === "object") ? _PP.CARD_MEDIA : {};

// A faded header photo shown at the top of a detail sheet. Renders nothing without an image.
function CardHeader({ mediaKey }) {
  const m = CARD_MEDIA[mediaKey];
  if (!m || !m.src) return null;
  const x = m.x ?? 50, y = m.y ?? 50, scale = m.scale ?? 1;
  return (
    <div style={{ position: "relative", margin: "0 -20px", height: 156, overflow: "hidden" }}>
      <img src={m.src} alt="" style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover", objectPosition: `${x}% ${y}%`, transform: `scale(${scale})`, transformOrigin: `${x}% ${y}%` }} />
      <div style={{ position: "absolute", inset: 0, background: "linear-gradient(to bottom, rgba(255,255,255,0) 42%, #ffffff 100%)" }} />
    </div>
  );
}

// Fixed card ids shared with the admin editor (Card photos). Map a sheet's display
// label / kind to the id so both sides agree on the CARD_MEDIA key.
function snapMediaId(label) {
  const l = String(label || "").toLowerCase();
  if (l.startsWith("location")) return "location";
  if (l.startsWith("commod")) return "commodity";
  if (l.startsWith("deposit")) return "depositType";
  if (l.startsWith("land")) return "landPosition";
  return "";
}
function cardMediaId(kindOrLabel) {
  const k = String(kindOrLabel || "").toLowerCase();
  if (k.includes("district") || k === "map") return "district";
  if (k.includes("strategy") || k.includes("history")) return "strategy";
  if (k.includes("geolog")) return "geology";
  if (k.includes("result") || k.includes("drill")) return "results";
  return "";
}
