// Subtle haptic feedback on selection (no-op where unsupported).
function haptic() { try { if (navigator.vibrate) navigator.vibrate(7); } catch (e) {} }

// Split a status value into distinct points. Points may be separated by a SPACED tilde,
// a bullet, a pipe, a newline, or a semicolon — but an inline approximation like "~40%"
// (tilde with no surrounding spaces) is left untouched. Leading bullet/tilde chars are stripped.
function splitStatusPoints(v) {
  return String(v || "")
    .split(/\s+~\s+|\s+[•|]\s+|\n+|;\s+/)
    .map((s) => s.replace(/^[-•~]\s*/, "").trim())
    .filter(Boolean);
}
// Renders a status value: a single point as plain text, multiple points as a bulleted list
// (real "•" dots, never a stray "~").
function StatusPoints({ text, className = "mt-1 text-[11px] font-semibold leading-tight tracking-tight text-slate-600" }) {
  const pts = splitStatusPoints(text);
  if (pts.length <= 1) return <p className={className}>{text || "—"}</p>;
  return (
    <ul className={className + " space-y-0.5"}>
      {pts.map((p, i) => (
        <li key={i} className="flex gap-1.5">
          <span aria-hidden="true" className="flex-shrink-0" style={{ color: EM_TEXT }}>•</span>
          <span>{p}</span>
        </li>
      ))}
    </ul>
  );
}

