// Resolved at render time (not module init) so esbuild can't inline the base64.
// Uses LC_SITE_GALLERY — the same photos the Projects page already ships — so the
// feed costs no additional image payload. Referencing a separate gallery would force
// esbuild to retain that whole array (dynamic index = no per-element tree-shaking).
function updateImg(post) {
  if (post.img) return post.img;
  if (post.imgIdx == null) return null;
  const slide = LC_SITE_GALLERY[post.imgIdx];
  return slide ? slide.src : null;
}

