// ===== Capital page helpers =====
const capNum = (s) => Number(String(s).replace(/[^0-9.]/g, "")) || 0;
const capFmt = (n) => capNum(n).toLocaleString("en-US");
const capShort = (n) => {
  const v = capNum(n);
  if (v >= 1e9) return (v / 1e9).toFixed(1).replace(/\.0$/, "") + "B";
  if (v >= 1e6) return (v / 1e6).toFixed(1).replace(/\.0$/, "") + "M";
  if (v >= 1e3) return (v / 1e3).toFixed(1).replace(/\.0$/, "") + "K";
  return String(v);
};
// Pull the lead money figure out of a verbose extracted string so a snapshot tablet
// shows a KEY NUMBER ("$41.6M") not a sentence ("$41.6 million (closing cash balance
// as of…)"). The full text still shows in the tap-through detail sheet.
const moneyShort = (s) => {
  const str = String(s || "").trim();
  if (!str) return str;
  const m = str.match(/((?:US\$|C\$|A\$|€|£|\$)?)\s?(\d[\d,]*(?:\.\d+)?)\s*(billion|million|thousand|bn\b|mm?\b|k\b)?/i);
  if (!m) return str.length > 14 ? str.slice(0, 13).trim() + "…" : str;
  const cur = (m[1] || "").replace(/\s+/g, "");
  const raw = Number(String(m[2]).replace(/,/g, "")) || 0;
  const word = (m[3] || "").toLowerCase();
  // Scale by the magnitude word if one is present; otherwise infer it from the number
  // itself, so a fully-written figure like "C$23,000,000" becomes "C$23M" instead of
  // overflowing the tile. The verbatim figure still shows in the tap-through sheet.
  const val = /b/.test(word) ? raw * 1e9 : /m/.test(word) ? raw * 1e6 : /k|thousand/.test(word) ? raw * 1e3 : raw;
  const abbr = val >= 1e9 ? (val / 1e9).toFixed(1).replace(/\.0$/, "") + "B"
    : val >= 1e6 ? (val / 1e6).toFixed(1).replace(/\.0$/, "") + "M"
    : val >= 1e3 ? (val / 1e3).toFixed(1).replace(/\.0$/, "") + "K"
    : String(raw);
  return cur + abbr;
};

function ScoreDots({ level, tone }) {
  const [on, setOn] = useState(false);
  const ref = useRef(null);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (typeof IntersectionObserver === "undefined") { setOn(true); return; }
    const io = new IntersectionObserver((entries) => {
      if (entries.some((e) => e.isIntersecting)) { setOn(true); io.disconnect(); }
    }, { threshold: 0.5, rootMargin: "0px 0px -8% 0px" });
    io.observe(el);
    return () => io.disconnect();
  }, []);
  return (
    <span ref={ref} className="flex items-center gap-[7px]">
      {[1, 2, 3, 4, 5].map((n) => {
        const active = n <= level;
        return (
          <span
            key={n}
            className="rounded-full"
            style={{
              height: 9,
              width: 9,
              background: on && active ? tone : "#e2e8f0",
              transform: on ? "scale(1)" : "scale(0.78)",
              transition: `background-color .8s ease ${n * 150}ms, transform .8s cubic-bezier(.22,1,.36,1) ${n * 150}ms`,
            }}
          />
        );
      })}
    </span>
  );
}

