function DilutionViz({ basic, fd }) {
  const frac = fd > 0 ? Math.min(100, (basic / fd) * 100) : 0;
  const [w, setW] = useState(0);
  useEffect(() => { const t = setTimeout(() => setW(frac), 140); return () => clearTimeout(t); }, [frac]);
  return (
    <div>
      <div className="h-2 w-full overflow-hidden rounded-full" style={{ background: "#e2e8f0" }}>
        <div className="h-full rounded-full" style={{ width: w + "%", background: "#0f172a", transition: "width .85s cubic-bezier(.22,1,.36,1)" }} />
      </div>
      <div className="mt-2 flex items-center gap-4">
        <span className="flex items-center gap-1.5 text-[10px] font-semibold text-slate-500"><span className="h-1.5 w-1.5 rounded-full" style={{ background: "#0f172a" }} />Basic Shares</span>
        <span className="flex items-center gap-1.5 text-[10px] font-semibold text-slate-400"><span className="h-1.5 w-1.5 rounded-full" style={{ background: "#cbd5e1" }} />Potential Dilution</span>
      </div>
    </div>
  );
}

const SEC_GROUPS = [
  { key: "Common Shares", match: (s) => /common/i.test(s) },
  { key: "Options", match: (s) => /option/i.test(s) },
  { key: "Warrants", match: (s) => /warrant/i.test(s) },
  { key: "Restricted Shares", match: (s) => /restricted/i.test(s) },
  { key: "Convertible Securities", match: (s) => /convert/i.test(s) },
];

// Gradient AI summary card — mirrors the app's feature-card pattern
// (radial highlight + directional fill + coloured shadow). Blue→violet accent.
function AISummaryButton({ onClick }) {
  return (
    <button
      onClick={onClick}
      className="relative w-full appearance-none overflow-hidden rounded-2xl px-4 py-3.5 text-left transition active:scale-[0.99]"
      style={{
        border: "none",
        outline: "none",
        background: "radial-gradient(135% 130% at 88% 6%, rgba(150,120,255,0.55) 0%, rgba(150,120,255,0) 46%), linear-gradient(140deg, #2540c8 0%, #4f46e5 56%, #7c3aed 100%)",
        boxShadow: "0 18px 36px -18px rgba(79,70,229,0.65)",
      }}
    >
      <span aria-hidden="true" className="pointer-events-none absolute inset-x-0 top-0" style={{ height: "52%", background: "linear-gradient(180deg, rgba(255,255,255,0.18), rgba(255,255,255,0))" }} />
      <span className="relative flex items-center gap-2.5">
        <span className="grid h-7 w-7 flex-shrink-0 place-items-center rounded-full" style={{ background: "rgba(255,255,255,0.18)", border: "1px solid rgba(255,255,255,0.3)" }}>
          <Sparkles size={14} color="#fff" strokeWidth={2.4} />
        </span>
        <span className="flex-1">
          <span className="block text-[12.5px] font-bold tracking-tight text-white">AI Summary</span>
          <span className="block text-[10.5px] font-medium" style={{ color: "rgba(255,255,255,0.72)" }}>Plain-English read on this capital structure</span>
        </span>
        <ChevronRight size={16} className="flex-shrink-0" strokeWidth={2.4} style={{ color: "rgba(255,255,255,0.8)" }} />
      </span>
    </button>
  );
}

// Company-specific interpretation of a metric. Replaces generic finance definitions.
// Styling is identical to the educational block it supersedes — no visual change.
function CompanyContext({ children }) {
  if (!children) return null;
  return (
    <div className="mt-5 space-y-3.5 border-t border-slate-100 pt-4">
      <div>
        <p className="text-[10px] font-bold uppercase tracking-wider" style={{ color: "#2563eb" }}>Company Context</p>
        <p className="mt-1 text-[12.5px] font-medium leading-relaxed text-slate-600">{children}</p>
      </div>
    </div>
  );
}

// Standardized provenance footer — appears at the bottom of every Capital card.
function CapitalFooter() {
  return (
    <div className="mt-4 border-t border-slate-100 pt-3">
      <p className="text-[10px] font-bold uppercase tracking-wider text-slate-400">Source</p>
      <p className="mt-1 text-[10px] font-medium leading-relaxed text-slate-400">
        Passport AI analyzed the company's latest public filings, financial statements, MD&amp;A, news releases and regulatory disclosures.
      </p>
      <p className="mt-1.5 text-[10px] font-medium leading-relaxed text-slate-400">
        Information is provided for informational purposes only and is not investment advice.
      </p>
    </div>
  );
}

// Navigation row that opens a bottom sheet. Icon chip + title + preview + chevron.
function SectionRow({ Icon, label, preview, onClick, first }) {
  return (
    <button
      onClick={onClick}
      className={`flex w-full appearance-none items-center gap-3 px-4 py-3.5 text-left transition active:bg-slate-50 ${first ? "" : "border-t border-slate-100"}`}
      style={{ border: "none", background: "transparent", outline: "none" }}
    >
      <span className="grid h-9 w-9 flex-shrink-0 place-items-center rounded-xl" style={{ background: "rgba(37,99,235,0.10)" }}>
        <Icon size={17} style={{ color: "#2563eb" }} strokeWidth={2.3} />
      </span>
      <span className="min-w-0 flex-1">
        <span className="block text-[13px] font-bold tracking-tight text-slate-900">{label}</span>
        <span className="block truncate text-[11px] font-medium tracking-tight text-slate-400">{preview}</span>
      </span>
      <ChevronRight size={16} className="flex-shrink-0 text-slate-300" strokeWidth={2.4} />
    </button>
  );
}

function CapitalView() {
  // Single sheet controller — null, or one of:
  // "structure" | "ownership" | "financing" | "finDetails" | "aiSummary"
  const [sheet, setSheet] = useState(null);
  const [listing, setListing] = useState(null);
  const [metricKey, setMetricKey] = useState(null);
  const [eduKey, setEduKey] = useState(null);
  const [runwayTarget, setRunwayTarget] = useState(0);
  const runwayW = useTween(runwayTarget, 1100);
  useEffect(() => { const t = setTimeout(() => setRunwayTarget(CAPSTATUS.runwayPct), 200); return () => clearTimeout(t); }, []);

  const raises = Array.isArray(RAISES) ? RAISES : [];
  const hasRaise = raises.length > 0;
  const r0 = raises[0] || {};   // safe: an empty file has no financing, so never index a missing raise
  const debtNum = capNum(COMPANY.debt);
  const equityNum = capNum(COMPANY.equity) || capNum(COMPANY.workingCapital);
  const dte = debtNum === 0 ? "0%" : `${Math.round((debtNum / equityNum) * 100)}%`;

  // ===== Capital Snapshot — the four metrics investors actually check =====
  // Basic/Fully Diluted are pulled from CAP (single source of truth) so they
  // can never drift from the Share Structure breakdown below.
  // TODO(JJ): swap the cash figure here when the C$4.2M / C$13.0M call is final.
  const CASH_VALUE = COMPANY.cash;            // <-- change this one line
  const CASH_ASOF  = "As of Mar 31, 2026";    // <-- and this stamp
  const snapshot = [
    { k: "Latest Financing", v: hasRaise ? moneyShort(r0.v) : "—", sub: hasRaise ? `${r0.type || "Financing"} · ${r0.d}`.replace(/^ · | · $/g, "") : "None disclosed" },
    { k: "Cash", v: moneyShort(CASH_VALUE), sub: CASH_ASOF },
    { k: "Basic Shares", v: capShort(capNum(CAP.outstanding)) },
    { k: "Fully Diluted", v: capShort(capNum(CAP.fd)) },
  ].filter((m) => m.v);

  // Balance sheet — reported figures only, in the specified order.
  // Rows without a reported figure are hidden rather than shown as placeholders.
  const finDetails = [
    { k: "Cash", v: COMPANY.cash },
    { k: "Working Capital", v: COMPANY.workingCapital },
    { k: "Current Ratio", v: COMPANY.currentRatio },
    { k: "Long-Term Debt", v: COMPANY.debt },
    // Data-driven — was hardcoded to Kingsmen's "Mar 31, 2026" / "Q1 2026 Interim MD&A",
    // which showed as fact on every company. Now hides when the company hasn't supplied it.
    { k: "Reporting Date", v: COMPANY.reportingDate },
    { k: "Latest Filing", v: COMPANY.latestFiling },
  ].filter((m) => m.v);

  const updated = new Date().toLocaleDateString("en-US", { month: "short", day: "numeric" });
  const capTone = CAP_TONE[CAP_STATES[CAPSTATUS.state] || "ok"] || CAP_TONE.ok;

  // ===== Share-structure computation (used by tablet + bottom sheet) =====
  const basic = capNum(CAP.outstanding), fd = capNum(CAP.fd);
  const ssGroups = SEC_GROUPS.map((g) => {
    const rows = CAP.rows.filter((r) => g.match(r.sec));
    return { ...g, rows, total: rows.reduce((a, r) => a + capNum(r.qty), 0) };
  }).filter((g) => g.rows.length > 0);
  const priceOf = (det) => { const m = (det || "").match(/\$([0-9.]+)/); return m ? parseFloat(m[1]) : null; };
  const calcGroup = (re) => {
    const g = ssGroups.find((x) => re.test(x.key));
    if (!g) return null;
    let qty = 0, proceeds = 0;
    g.rows.forEach((r) => { const p = priceOf(r.det); const q = capNum(r.qty); if (p != null && q) { qty += q; proceeds += p * q; } });
    return qty > 0 ? { proceeds, avg: proceeds / qty } : null;
  };
  const optCalc = calcGroup(/option/i), warCalc = calcGroup(/warrant/i);
  const totalProceeds = (optCalc ? optCalc.proceeds : 0) + (warCalc ? warCalc.proceeds : 0);
  const money = (n) => "C$" + (n >= 1e6 ? (n / 1e6).toFixed(1) + "M" : (n / 1e3).toFixed(0) + "K");
  const dilutionPct = fd > 0 ? (((fd - basic) / fd) * 100).toFixed(1) + "%" : NR;

  // ===== Pre-written AI summary of the capital structure =====
  const AI_SUMMARY = [
    { h: "Capital Position", b: `${COMPANY.name} carries no debt and a tight ${capShort(basic)} basic share count, reaching ${capShort(fd)} fully diluted — a ${dilutionPct} potential dilution that is modest for an explorer at this stage.` },
    { h: "Funding", b: `The ${r0.v} ${(r0.type||"").toLowerCase()} in ${r0.d} is the most recent raise. A bought deal means an underwriter took the financing risk onto its own book before reselling the offering.` },
    { h: "Ownership", b: OWNERSHIP.length ? OWNERSHIP.map(([k, v]) => `${k}: ${v}.`).join(" ") : `Ownership breakdown has not been reported for ${COMPANY.name} yet.` },
    { h: "Key Considerations", b: `Options and warrants would bring in roughly ${money(totalProceeds)} of cash if exercised, but also account for all of the dilution between basic and fully diluted. Most warrants sit above the current share price.` },
  ];

  const proceedsStr = totalProceeds > 0 ? money(totalProceeds) : null;

  // ===== Company Context — specific to this company, not finance in general =====
  const CTX = {
    cash: `${COMPANY.name}'s reported cash balance of ${COMPANY.cash} appears sufficient alongside its recently completed ${r0.v} ${(r0.type||"").toLowerCase()}. Investors typically compare this figure against the company's planned exploration program to estimate funding runway.`,
    basicShares: `At ${capShort(basic)} basic shares, ${COMPANY.name} carries an unusually tight share count for a TSX-V explorer at this stage. Each share therefore represents a larger claim on any future discovery than it would at a company with a heavily issued float.`,
    fullyDiluted: `If every outstanding option and warrant were exercised today, ${COMPANY.name}'s share count would rise from ${capShort(basic)} to ${capShort(fd)} — diluting existing ownership by ${dilutionPct}.${proceedsStr ? ` The company would also receive approximately ${proceedsStr} in new capital.` : ""}`,
    latestFinancing: `${COMPANY.name} completed a ${r0.v}${r0.type ? ` ${String(r0.type).toLowerCase()}` : ""}${r0.d ? ` in ${r0.d}` : ""}${r0.price ? ` at ${r0.price} per share` : ""}${r0.purpose ? `, earmarked for ${String(r0.purpose).toLowerCase()}` : ""}.${/bought\s*deal/i.test(r0.type || "") ? " In a bought deal the underwriter purchases the offering onto its own book before reselling it, so the financing is fully committed at pricing." : ""}`,
    balanceSheet: `${COMPANY.name} reports ${(COMPANY.debt && !/^\D*0(\.0+)?\D*$/.test(COMPANY.debt)) ? `long-term debt of ${COMPANY.debt}` : "no long-term debt"}${COMPANY.cash ? ` alongside a cash balance of ${COMPANY.cash}` : ""}${COMPANY.workingCapital ? ` and working capital of ${COMPANY.workingCapital}` : ""}.`,
    status: `${CAPSTATUS.summary} This reading reflects ${COMPANY.name}'s own reported cash and its most recent financing — it is a factual comparison, not a rating or forecast.`,
    structure: `${COMPANY.name}'s structure is tight for an explorer at this stage: ${capShort(basic)} basic shares, with options and warrants accounting for the full ${dilutionPct} gap to ${capShort(fd)} fully diluted.${proceedsStr ? ` Exercising them all would bring roughly ${proceedsStr} into treasury.` : ""}`,
    ownership: OWNERSHIP.length ? OWNERSHIP.map(([k, v]) => `${k}: ${v}.`).join(" ") : `Ownership breakdown has not been reported in ${COMPANY.name}'s public filings yet.`,
    snapshot: `These four figures describe ${COMPANY.name}'s funding position today: what it last raised, what it holds, and how many shares that value is spread across. Tap any tile for the reported figures behind it.`,
  };

  // ===== Snapshot tablet → which sheet/metric each opens =====
  const tabletAction = {
    "Latest Financing": () => setSheet("financing"),
    "Cash": () => setMetricKey("Cash"),
    "Basic Shares": () => setMetricKey("Basic Shares"),
    "Fully Diluted": () => setMetricKey("Fully Diluted"),
  };

  return (
    <>
    <div className="space-y-6 px-5 pt-2">
      <div>
        <Kicker section="capital" />
        <h2 className="-mt-0.5 text-xl font-bold tracking-tight text-slate-900">Capital</h2>
      </div>

      {/* ===== CAPITAL STATUS CARD (the only shadowed element on the page) ===== */}
      <div className="overflow-hidden rounded-3xl border border-slate-200 bg-white" style={{ boxShadow: cardShadow }}>
        <div className="px-5 pb-5 pt-5">
          <div className="flex items-center justify-between">
            <span className="inline-flex items-center gap-1.5 rounded-full px-2.5 py-1" style={{ border: `1px solid ${capTone.ring}`, background: "transparent" }}>
              <span className="relative flex h-1.5 w-1.5">
                <span className="pp-ping absolute inline-flex h-full w-full rounded-full opacity-75" style={{ background: capTone.dot }} />
                <span className="relative inline-flex h-1.5 w-1.5 rounded-full" style={{ background: capTone.dot }} />
              </span>
              <span className="font-extrabold uppercase" style={{ fontSize: 9, letterSpacing: "0.14em", color: capTone.text }}>{CAPSTATUS.state || "Capital Status"}</span>
            </span>
            <button onClick={() => { haptic(); setSheet("status"); }} aria-label="Why this status" className="-mr-1 grid appearance-none place-items-center rounded-full transition active:scale-90" style={{ height: 24, width: 24, background: "transparent", border: "none", outline: "none" }}>
              <Info size={18} style={{ color: "#2563eb" }} strokeWidth={2.4} />
            </button>
          </div>
          <h2 className="font-extrabold tracking-tight text-slate-900" style={{ marginTop: 13, fontSize: 25, lineHeight: 1.06 }}>{CAPSTATUS.headline}</h2>
          <p className="font-medium text-slate-500" style={{ marginTop: 9, fontSize: 12.5, lineHeight: 1.4 }}>{CAPSTATUS.summary}</p>
          <div style={{ marginTop: 22 }}>
            <p className="px-1 text-[10px] font-bold uppercase tracking-wider text-slate-400">Funding Runway</p>
            <div className="relative mt-3 flex h-5 items-center px-1">
              <div className="relative h-2 w-full rounded-full bg-slate-200">
                <div className="absolute inset-y-0 left-0 rounded-full" style={{ width: `${runwayW}%`, background: "linear-gradient(90deg, #2563eb, #60a5fa)" }} />
                <div className="absolute z-10 h-4 w-4 rounded-full" style={{ left: `${runwayW}%`, top: "50%", transform: "translate(-50%, -50%)", background: "#1d4ed8", boxShadow: "0 0 0 2.5px #fff, 0 0 0 4.5px rgba(37,99,235,0.35), 0 2px 6px -1px rgba(0,0,0,0.25)" }} />
              </div>
            </div>
            <div className="mt-1.5 flex justify-between px-1">
              <span className="text-[10px] font-bold uppercase tracking-wider text-slate-400">{CAPSTATUS.runwayLeft}</span>
              <span className="text-[10px] font-extrabold uppercase tracking-wider" style={{ color: "#2563eb" }}>{CAPSTATUS.runwayRight}</span>
            </div>
          </div>
        </div>
      </div>

      {/* ===== LISTINGS (directly beneath the status card) ===== */}
      {EXCHANGES.length > 0 && (
        <div>
          <div className="flex items-baseline justify-between px-0.5">
            <span className={subLabel}>Listings</span>
            <span className="text-[9px] font-semibold uppercase tracking-wider text-slate-300">Delayed 15 min</span>
          </div>
          <div className="mt-2.5 grid grid-cols-3 gap-2.5">
            {EXCHANGES.map((x) => (
              <ListingCard key={x.sym} x={x} onOpen={setListing} />
            ))}
          </div>
        </div>
      )}

      {/* ===== AI SUMMARY (top) ===== */}
      <AISummaryButton onClick={() => { haptic(); setSheet("aiSummary"); }} />

      {/* ===== CAPITAL SNAPSHOT — 4 tappable grey tablets ===== */}
      {snapshot.length > 0 && (
        <div>
          <div className="flex items-center justify-between px-0.5">
            <span className={subLabel}>Capital Snapshot</span>
            <button onClick={() => { haptic(); setEduKey("snapshot"); }} aria-label="About these metrics" className="appearance-none p-0.5" style={{ border: "none", background: "transparent", outline: "none" }}>
              <Info size={14} style={{ color: "#cbd5e1" }} strokeWidth={2.4} />
            </button>
          </div>
          <div className="mt-2.5 grid grid-cols-2 gap-3">
            {snapshot.map((s, i) => {
              const TIcon = { "Market Cap": Landmark, "Cash": Wallet, "Basic Shares": Layers, "Fully Diluted": PieChart }[s.k] || Coins;
              const fcKey = "capital." + ({ "Market Cap": "marketCap", "Cash": "cash", "Basic Shares": "outstanding", "Fully Diluted": "fd" }[s.k] || String(s.k).toLowerCase().replace(/\s+/g, ""));
              return (
                <button
                  key={i}
                  data-fc={fcKey}
                  onClick={() => { haptic(); (tabletAction[s.k] || (() => {}))(); }}
                  className="relative appearance-none rounded-2xl bg-slate-50 p-5 text-left transition active:scale-[0.98]"
                  style={{ border: "none", outline: "none" }}
                >
                  <span className="grid h-8 w-8 place-items-center rounded-xl" style={{ background: "rgba(37,99,235,0.10)" }}>
                    <TIcon size={16} style={{ color: "#2563eb" }} strokeWidth={2.3} />
                  </span>
                  <p className="mt-3 text-[22px] font-extrabold leading-none tracking-tight text-slate-900 tabular-nums">{s.v}</p>
                  <p className="mt-2.5 text-[10px] font-semibold uppercase tracking-wider text-slate-400">{s.k}</p>
                  {s.sub && <p className="mt-1 text-[10px] font-medium tracking-tight text-slate-400">{s.sub}</p>}
                  <ChevronRight size={13} className="absolute right-3 top-3" style={{ color: "#cbd5e1" }} />
                </button>
              );
            })}
          </div>
        </div>
      )}

      {/* ===== SECTION CARDS (tap to open detail sheet) ===== */}
      <div>
        <span className={`${subLabel} px-0.5`}>Explore</span>
        <div className="mt-2.5 overflow-hidden rounded-2xl border border-slate-200 bg-white">
          <SectionRow Icon={Layers} label="Share Structure" preview={`${capShort(basic)} basic · ${capShort(fd)} fully diluted`} onClick={() => { haptic(); setSheet("structure"); }} first />
          <SectionRow Icon={Users} label="Ownership" preview={OWNERSHIP.length ? OWNERSHIP.map(([k, v]) => `${String(k).replace(/\s*ownership/i, "")} ${v}`).join(" · ").trim() : "Not yet reported"} onClick={() => { haptic(); setSheet("ownership"); }} />
          <SectionRow Icon={Activity} label="Balance Sheet" preview="Cash, working capital, debt" onClick={() => { haptic(); setSheet("finDetails"); }} />
        </div>
      </div>
    </div>

    {metricKey && (() => {
      const titleMap = { "Cash": "Cash", "Basic Shares": "Basic Shares", "Fully Diluted": "Fully Diluted Shares" };
      const ctxMap = { "Cash": CTX.cash, "Basic Shares": CTX.basicShares, "Fully Diluted": CTX.fullyDiluted };
      // Fully Diluted is computed from live share-structure figures, not a static table.
      const fdRows = [
        ["Fully Diluted Shares", CAP.fd],
        ["Potential Dilution", dilutionPct],
        ["Potential Exercise Proceeds", proceedsStr || NR],
      ];
      const rows = metricKey === "Fully Diluted" ? fdRows : METRIC_DETAIL[metricKey];
      return (
        <BottomSheet onClose={() => setMetricKey(null)}>
          <SheetHeader kicker={metricKey} title={titleMap[metricKey] || metricKey} />

          <div className="mt-4">
            {(rows || []).map((d, i) => (
              <div key={i} className="flex items-start justify-between gap-3 border-t border-slate-100 py-2.5 first:border-t-0">
                <span className="text-[10.5px] font-semibold uppercase tracking-wider text-slate-400">{d[0]}</span>
                <span className="text-right text-[12.5px] font-semibold tabular-nums tracking-tight text-slate-700">{d[1] || NR}</span>
              </div>
            ))}
          </div>

          <CompanyContext>{ctxMap[metricKey]}</CompanyContext>
          <CapitalFooter />
        </BottomSheet>
      );
    })()}

    {eduKey && EDU[eduKey] && (
      <BottomSheet onClose={() => setEduKey(null)}>
        <SheetHeader kicker="About" title={EDU[eduKey].t} />
        <CompanyContext>{CTX.snapshot}</CompanyContext>
        <CapitalFooter />
      </BottomSheet>
    )}

    {/* ===== LISTING → OPEN IN YAHOO PROMPT (centered dialog) ===== */}
    {listing && (
      <div
        className="absolute inset-0 z-50 flex items-center justify-center px-6"
        style={{ background: "rgba(15,23,42,0.4)", backdropFilter: "blur(6px)" }}
        onClick={() => setListing(null)}
      >
        <div
          className="w-full max-w-[300px] rounded-[26px] bg-white px-7 pb-6 pt-8"
          style={{ boxShadow: "0 24px 70px -16px rgba(15,23,42,0.5)" }}
          onClick={(e) => e.stopPropagation()}
        >
          <div className="flex flex-col items-center text-center">
            <span className="grid h-12 w-12 place-items-center rounded-2xl" style={{ background: "rgba(124,58,237,0.1)" }}>
              <ArrowUpRight size={22} style={{ color: "#7c3aed" }} strokeWidth={2.6} />
            </span>
            <p className="mt-5 text-[9px] font-bold uppercase tracking-[0.2em] text-slate-400">{listing.ex} · {listing.sym}</p>
            <p className="mt-2 text-[18px] font-extrabold leading-tight tracking-tight text-slate-900">Open in Yahoo Finance</p>
            <p className="mt-2 text-[12.5px] font-medium leading-relaxed text-slate-500">View live market data for {listing.sym} in your browser.</p>
          </div>
          <div className="mt-6 flex justify-center">
            <a
              href={`https://finance.yahoo.com/quote/${listing.yahoo}`}
              target="_blank"
              rel="noopener noreferrer"
              onClick={() => setListing(null)}
              className="inline-flex items-center justify-center rounded-full px-7 py-3 text-[13.5px] font-bold text-white transition active:scale-[0.97]"
              style={{ background: "#7c3aed" }}
            >
              Open Live Market Data
            </a>
          </div>
          <button
            onClick={() => setListing(null)}
            className="mt-1.5 w-full py-2.5 text-[13px] font-bold text-slate-400 transition active:scale-[0.97]"
          >
            Cancel
          </button>
        </div>
      </div>
    )}

    {/* ===== SHARE STRUCTURE SHEET ===== */}
    {sheet === "structure" && (
      <BottomSheet onClose={() => setSheet(null)}>
        <SheetHeader kicker="Capital" title="Share Structure" />
        <SheetStatGrid items={[
          { label: "Basic Shares", value: capShort(basic) },
          ...(fd > 0 ? [{ label: "Fully Diluted", value: capShort(fd) }] : []),
        ]} />
        {fd > 0 && <div className="mt-4"><DilutionViz basic={basic} fd={fd} /></div>}
        {ssGroups.map((g, gi) => {
          const tranches = g.rows.filter((r) => r.det && r.det !== "\u2014");
          return (
            <div key={gi} className="mt-4 border-t border-slate-100 pt-4">
              <div className="flex items-baseline justify-between">
                <span className="text-[13px] font-bold tracking-tight text-slate-900">{g.key}</span>
                <span className="text-[13px] font-bold tabular-nums tracking-tight text-slate-900">{capFmt(g.total)}</span>
              </div>
              {tranches.length > 0 && (
                <div className="mt-2.5 space-y-2">
                  {tranches.map((r, ri) => (
                    <div key={ri} className="flex items-center justify-between gap-3">
                      <span className="text-[11px] font-medium text-slate-400">{r.det}</span>
                      <span className="text-[11.5px] font-medium tabular-nums tracking-tight text-slate-500">{r.qty}</span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          );
        })}
        {fd > 0 && <SheetRow label="Potential Dilution" value={dilutionPct} />}
        {proceedsStr && <SheetRow label="Potential Exercise Proceeds" value={proceedsStr} />}
        {(optCalc || warCalc) && (
          <SheetSection title="Potential Exercise Proceeds">
            <div className="flex items-end justify-between gap-3">
              <span className="text-[11px] font-medium leading-snug text-slate-500">If all outstanding options<br />and warrants were exercised</span>
              <span className="text-[15px] font-extrabold tabular-nums tracking-tight text-slate-900">{money(totalProceeds)}</span>
            </div>
            <div className="mt-3 space-y-2">
              <div className="flex items-center justify-between">
                <span className="text-[11px] font-medium text-slate-400">Options · Weighted Avg</span>
                <span className="text-[11.5px] font-medium tabular-nums text-slate-600">{optCalc ? "C$" + optCalc.avg.toFixed(2) : NR}</span>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-[11px] font-medium text-slate-400">Warrants · Weighted Avg</span>
                <span className="text-[11.5px] font-medium tabular-nums text-slate-600">{warCalc ? "C$" + warCalc.avg.toFixed(2) : NR}</span>
              </div>
            </div>
          </SheetSection>
        )}
        {fd > 0 && <SheetRow label="Fully Diluted Total" value={CAP.fd} strong />}
        <CompanyContext>{CTX.structure}</CompanyContext>
        <CapitalFooter />
      </BottomSheet>
    )}

    {/* ===== OWNERSHIP SHEET ===== */}
    {sheet === "ownership" && (
      <BottomSheet onClose={() => setSheet(null)}>
        <SheetHeader kicker="Capital" title="Ownership" />
        <div className="mt-2">
          {OWNERSHIP.map(([k, v], i) => (
            <div key={i} className={`flex items-center justify-between gap-3 py-3.5 ${i === 0 ? "" : "border-t border-slate-100"}`}>
              <span className="text-[13px] font-semibold tracking-tight text-slate-900">{k}</span>
              <span className="text-[13px] font-semibold tabular-nums tracking-tight text-slate-700">{v}</span>
            </div>
          ))}
        </div>
        <CompanyContext>{CTX.ownership}</CompanyContext>
        <CapitalFooter />
      </BottomSheet>
    )}

    {/* ===== LATEST FINANCING SHEET ===== */}
    {sheet === "financing" && (
      <BottomSheet onClose={() => setSheet(null)}>
        <SheetHeader kicker="Financing" title="Latest Financing" accent={EM_TEXT} />
        {!hasRaise ? (
          <p className="mt-4 text-[13.5px] font-medium leading-relaxed text-slate-500">No financings have been disclosed for this company yet.</p>
        ) : (<>
        <div className="mt-4 flex items-baseline justify-between">
          <span className="text-[22px] font-extrabold tabular-nums tracking-tight" style={{ color: EM_TEXT }}>{r0.v}</span>
          <span className="text-[11px] font-bold uppercase tracking-wider text-slate-400">{r0.d}</span>
        </div>
        <p className="text-[12.5px] font-medium text-slate-500">{r0.type}</p>
        <div className="mt-3">
          {[
            ["Status", r0.status || "Completed"],
            ["Type", r0.type],
            ["Amount Raised", r0.v],
            ["Date", r0.d],
            ["Price per Share", r0.price],
            ["Lead Broker", r0.lead],
            ["Use of Proceeds", r0.purpose],
          ].filter((d) => d[1] && String(d[1]).trim() && String(d[1]) !== NR).map((d, i) => (
            <div key={i} className="flex items-start justify-between gap-3 border-t border-slate-100 py-2.5">
              <span className="text-[10.5px] font-semibold uppercase tracking-wider text-slate-400">{d[0]}</span>
              <span className="text-right text-[12.5px] font-semibold tracking-tight text-slate-700">{d[1]}</span>
            </div>
          ))}
        </div>
        <CompanyContext>{CTX.latestFinancing}</CompanyContext>
        {r0.nr && (
          <a href={r0.nr} target="_blank" rel="noopener noreferrer" className="mt-4 flex items-center justify-between gap-3 rounded-2xl border border-slate-200 bg-white px-4 py-3 transition active:scale-[0.98]">
            <span className="text-[12.5px] font-semibold tracking-tight text-slate-700">Read the original news release</span>
            <ArrowUpRight size={16} className="flex-shrink-0 text-slate-400" strokeWidth={2.3} />
          </a>
        )}
        <CapitalFooter />
        <p className="mt-3 border-t border-slate-100 pt-3 text-[11.5px] font-medium leading-relaxed text-slate-500">A bought deal means an underwriter purchased the entire offering up front and took on the resale risk — generally read as a sign of confidence in the story.</p>
        </>)}
      </BottomSheet>
    )}

    {/* ===== BALANCE SHEET ===== */}
    {sheet === "finDetails" && (
      <BottomSheet onClose={() => setSheet(null)}>
        <SheetHeader kicker="Capital" title="Balance Sheet" />
        <div className="mt-2">
          {finDetails.map((m, i) => (
            <div key={i} className="flex items-center justify-between gap-3 border-t border-slate-100 py-3.5">
              <span className="text-[13px] font-semibold tracking-tight text-slate-900">{m.k}</span>
              <span className="text-[13px] font-semibold tabular-nums tracking-tight text-slate-700">{m.v}</span>
            </div>
          ))}
        </div>
        <CompanyContext>{CTX.balanceSheet}</CompanyContext>
        <CapitalFooter />
      </BottomSheet>
    )}

    {/* ===== CAPITAL STATUS SHEET (why this status was assigned) ===== */}
    {sheet === "status" && (
      <BottomSheet onClose={() => setSheet(null)}>
        <SheetHeader kicker="Capital Status" title={CAPSTATUS.state} />
        <div className="mt-4">
          <p className="text-[13px] font-medium leading-relaxed text-slate-600">{CAPSTATUS.summary}</p>
        </div>
        <div className="mt-4">
          {[
            ["Based On Financing", `${r0.v} ${(r0.type||"").toLowerCase()} · ${r0.d}`],
            ["Latest Reported Cash", COMPANY.cash],
            ["Reporting Date", "Mar 31, 2026"],
            ["Last Updated", updated],
          ].map((d, i) => (
            <div key={i} className="flex items-start justify-between gap-3 border-t border-slate-100 py-2.5">
              <span className="text-[10.5px] font-semibold uppercase tracking-wider text-slate-400">{d[0]}</span>
              <span className="text-right text-[12.5px] font-semibold tabular-nums tracking-tight text-slate-700">{d[1]}</span>
            </div>
          ))}
        </div>
        <CompanyContext>{CTX.status}</CompanyContext>
        <CapitalFooter />
      </BottomSheet>
    )}

    {/* ===== AI SUMMARY SHEET ===== */}
    {sheet === "aiSummary" && (
      <BottomSheet onClose={() => setSheet(null)}>
        <SheetHeader kicker="AI Summary" title="Capital structure at a glance" accent="#7c3aed" icon={Sparkles} iconBg="rgba(124,58,237,0.12)" />
        <div className="mt-4 space-y-3.5">
          {AI_SUMMARY.map((d, i) => (
            <div key={i}>
              <p className="text-[10px] font-bold uppercase tracking-wider" style={{ color: "#7c3aed" }}>{d.h}</p>
              <p className="mt-1 text-[12.5px] font-medium leading-relaxed text-slate-600">{d.b}</p>
            </div>
          ))}
        </div>
        <CapitalFooter />
      </BottomSheet>
    )}
    </>
  );
}

