// ============ Editorial expanded-card primitives (Apple-style reading experience) ============
function ExecLead({ children }) {
  return <p className="text-[14.5px] font-medium leading-relaxed text-slate-700">{children}</p>;
}
function CardSection({ heading, children }) {
  return (
    <div>
      <p className="text-[10px] font-bold uppercase tracking-[0.16em] text-slate-400">{heading}</p>
      <div className="mt-2">{children}</div>
    </div>
  );
}
// Two-column info table. Rows are [label, value]; any row with an empty value is hidden.
function InfoTable({ rows }) {
  const clean = (rows || []).filter((r) => r && r[1] != null && String(r[1]).trim() !== "");
  if (!clean.length) return null;
  return (
    <div className="overflow-hidden rounded-2xl border border-slate-100 bg-white">
      {clean.map(([k, v], i) => (
        <div key={i} className={`flex gap-4 px-4 py-3 ${i > 0 ? "border-t border-slate-50" : ""}`}>
          <span className="w-[38%] flex-shrink-0 text-[11px] font-semibold leading-snug text-slate-400">{k}</span>
          <span className="flex-1 text-[12.5px] font-semibold leading-snug text-slate-800">{v}</span>
        </div>
      ))}
    </div>
  );
}
function ClosingNote({ soft, accent, label = "The takeaway", children }) {
  if (!children) return null;
  return (
    <div className="border-l-2 pl-4" style={{ borderColor: accent }}>
      <p className="text-[10px] font-bold uppercase tracking-[0.16em]" style={{ color: accent }}>{label}</p>
      <p className="mt-1.5 text-[13.5px] font-medium leading-relaxed text-slate-700">{children}</p>
    </div>
  );
}
function BulletList({ items, accent }) {
  const clean = (items || []).filter(Boolean);
  if (!clean.length) return null;
  return (
    <ul className="space-y-1.5">
      {clean.map((b, i) => (
        <li key={i} className="flex gap-2.5 text-[12.5px] font-medium leading-snug text-slate-700">
          <span className="mt-[7px] h-1 w-1 flex-shrink-0 rounded-full" style={{ background: accent }} />
          <span>{b}</span>
        </li>
      ))}
    </ul>
  );
}
// A compact evidence/priority block: heading + description (+ optional status pill / fact).
function EvidenceRow({ name, desc, pill, soft, accent }) {
  return (
    <div className="rounded-2xl border border-slate-100 bg-slate-50 p-3.5">
      <div className="flex items-center justify-between gap-3">
        <p className="text-[13px] font-bold tracking-tight text-slate-900">{name}</p>
        {pill && <span className="flex-shrink-0 rounded-full px-2 py-0.5 text-[9px] font-bold uppercase tracking-wider" style={{ background: soft, color: accent }}>{pill}</span>}
      </div>
      {desc && <p className="mt-1 text-[12px] font-medium leading-snug text-slate-500">{desc}</p>}
    </div>
  );
}
// ---- Hero + visual-identity primitives (all render without image assets) ----
function shade(hex, f) {
  const n = parseInt(String(hex).replace("#", ""), 16);
  if (Number.isNaN(n)) return hex;
  const r = Math.round(((n >> 16) & 255) * f), g = Math.round(((n >> 8) & 255) * f), b = Math.round((n & 255) * f);
  return `rgb(${r},${g},${b})`;
}
function heroGradient(tone) { return `linear-gradient(145deg, ${tone} 0%, ${shade(tone, 0.7)} 100%)`; }
function HeroBand({ tone, Icon, eyebrow, headline, foot }) {
  return (
    <div className="relative overflow-hidden rounded-2xl px-4 py-3" style={{ background: heroGradient(tone) }}>
      <div className="pointer-events-none absolute inset-0" style={{ backgroundImage: "radial-gradient(circle at 86% 14%, rgba(255,255,255,0.28) 0, transparent 48%)" }} />
      <div className="relative flex items-center gap-3">
        {Icon && <span className="grid h-8 w-8 flex-shrink-0 place-items-center rounded-lg" style={{ background: "rgba(255,255,255,0.2)" }}><Icon size={15} className="text-white" strokeWidth={2.3} /></span>}
        <div className="min-w-0">
          {eyebrow && <p className="text-[8px] font-bold uppercase tracking-[0.18em] text-white/70">{eyebrow}</p>}
          {headline && <p className="text-[14px] font-extrabold leading-tight tracking-tight text-white">{headline}</p>}
          {foot && <p className="mt-0.5 text-[10.5px] font-semibold text-white/80">{foot}</p>}
        </div>
      </div>
    </div>
  );
}
function CommodityChips({ primary, secondary, accent }) {
  return (
    <div className="space-y-2.5">
      <div className="rounded-2xl px-5 py-4" style={{ background: heroGradient(accent) }}>
        <p className="text-[9px] font-bold uppercase tracking-[0.2em] text-white/70">Primary Commodity</p>
        <p className="text-[22px] font-extrabold tracking-tight text-white">{primary}</p>
      </div>
      {secondary && secondary.length > 0 && (
        <div className="flex flex-wrap gap-2">
          {secondary.map((s, i) => (
            <span key={i} className="rounded-xl border border-slate-200 bg-white px-3 py-2 text-[12.5px] font-bold tracking-tight text-slate-700">{s}</span>
          ))}
        </div>
      )}
    </div>
  );
}
function StatPills({ items, accent }) {
  const clean = (items || []).filter((x) => x && x[1] != null && String(x[1]).trim() !== "");
  if (!clean.length) return null;
  return (
    <div className="flex overflow-hidden rounded-2xl border border-slate-100 bg-slate-50">
      {clean.map(([k, v], i) => (
        <div key={i} className={`min-w-0 flex-1 px-2 py-4 text-center ${i > 0 ? "border-l border-white" : ""}`}>
          <p className="text-[18px] font-extrabold leading-none tracking-tight" style={{ color: accent }}>{v}</p>
          <p className="mt-1.5 text-[9px] font-bold uppercase tracking-[0.08em] text-slate-400">{k}</p>
        </div>
      ))}
    </div>
  );
}
function Roadmap({ steps, accent }) {
  const clean = (steps || []).filter(Boolean);
  if (!clean.length) return null;
  return (
    <div className="space-y-2">
      {clean.map((s, i) => (
        <div key={i} className="flex items-start gap-3 rounded-2xl border border-slate-100 bg-slate-50 p-3.5">
          <span className="grid h-6 w-6 flex-shrink-0 place-items-center rounded-full text-[11px] font-extrabold text-white" style={{ background: accent }}>{i + 1}</span>
          <p className="text-[12.5px] font-medium leading-snug text-slate-700">{s}</p>
        </div>
      ))}
    </div>
  );
}
function RockSchematic({ accent }) {
  return (
    <div className="overflow-hidden rounded-3xl border border-slate-100">
      <div className="relative" style={{ height: 140 }}>
        <div className="absolute inset-x-0 top-0" style={{ height: "20%", background: "linear-gradient(180deg,#eaf1f8,#e0e8f1)" }} />
        <div className="absolute inset-x-0" style={{ top: "20%", height: "28%", background: "#e8dccb" }} />
        <div className="absolute inset-x-0" style={{ top: "48%", height: "26%", background: "#ddd0bd" }} />
        <div className="absolute inset-x-0" style={{ top: "74%", height: "26%", background: "#d0c3ae" }} />
        <div className="absolute" style={{ left: "36%", top: "-12%", width: 11, height: "134%", background: accent, transform: "rotate(15deg)", borderRadius: 11, boxShadow: `0 0 18px ${accent}55` }} />
        <span className="absolute left-3.5 top-2 text-[8.5px] font-bold uppercase tracking-[0.12em] text-slate-500">Surface</span>
        <span className="absolute right-3.5 top-1/2 -translate-y-1/2 rounded-full bg-white/80 px-2 py-0.5 text-[8.5px] font-bold uppercase tracking-[0.1em]" style={{ color: accent }}>Vein</span>
        <span className="absolute bottom-2 left-3.5 text-[8.5px] font-bold uppercase tracking-[0.12em] text-slate-600">At depth</span>
      </div>
    </div>
  );
}
