// TODAY activity — real: the most recent press releases across published companies.
const FEED = (typeof window !== "undefined" && Array.isArray(window.__FEED__)) ? window.__FEED__ : [];
const relTime = (iso) => {
  const d = new Date(String(iso) + "T00:00:00");
  if (isNaN(d)) return "";
  const days = Math.max(0, Math.round((Date.now() - d.getTime()) / 86400000));
  if (days <= 0) return "today";
  if (days === 1) return "1d";
  if (days < 7) return days + "d";
  if (days < 30) return Math.round(days / 7) + "w";
  if (days < 365) return Math.round(days / 30) + "mo";
  return Math.round(days / 365) + "y";
};
const TODAY_ACTIVITY = FEED.map((f) => ({
  src: "Company", srcTag: f.key ? "Milestone" : "Update", co: f.co, when: relTime(f.date),
  t: f.headline, Icon: f.key ? Sparkles : Newspaper, live: true, slug: f.slug, coId: f.coId, logo: f.logo,
  // Carried so the feed row can expand into an inline reader without leaving the page.
  whatHappened: f.whatHappened || "", why: f.why || "", takeaways: Array.isArray(f.takeaways) ? f.takeaways : [], originalTitle: f.originalTitle || "",
}));

// Trending — the published companies (most recently active first).
const TRENDING = (() => {
  const latest = {};
  for (const f of FEED) if (!latest[f.slug] || String(f.date) > latest[f.slug]) latest[f.slug] = String(f.date);
  const labels = ["Latest news", "Most followed", "Recently active", "Featured"];
  return DIRECTORY.slice()
    .sort((a, b) => String(latest[b.slug] || "").localeCompare(String(latest[a.slug] || "")))
    .slice(0, 4)
    .map((c, i) => ({ ...c, metric: labels[i] || "Featured" }));
})();

// One compact activity card, reused by TODAY and FOLLOWING. Tapping the row expands an
// INLINE reader (headline, what happened, why it matters, key numbers) so the release can be
// read without leaving the feed; tapping again collapses it. A footer button opens the company.
function ActivityRow({ it, onOpen }) {
  const s = SRC[it.src] || SRC.Company;
  const [open, setOpen] = useState(false);
  const readable = !!(it.whatHappened || it.why || (it.takeaways && it.takeaways.length));
  const toggle = () => { haptic(); if (readable) setOpen((v) => !v); else if (it.live && onOpen) onOpen(it); };
  return (
    <div className="overflow-hidden rounded-2xl border border-slate-100 bg-white transition"
      style={{ boxShadow: "0 1px 2px rgba(15,23,42,0.04), 0 12px 26px -20px rgba(15,23,42,0.4)" }}>
      <button onClick={toggle} className="flex w-full items-start gap-3 p-3.5 text-left transition active:scale-[0.995]">
        <span className="grid h-9 w-9 flex-shrink-0 place-items-center rounded-xl" style={{ background: s.b }}><it.Icon size={16} style={{ color: s.c }} /></span>
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-1.5">
            <span className="rounded-md px-1.5 py-0.5 text-[8px] font-extrabold uppercase tracking-wider" style={{ background: s.b, color: s.c }}>{it.src}</span>
            <span className="truncate text-[11px] font-bold tracking-tight text-slate-400">{it.co}</span>
            <span className="ml-auto flex-shrink-0 text-[10.5px] font-semibold text-slate-300">{it.when}</span>
          </div>
          <p className="mt-1.5 text-[13.5px] font-bold leading-snug tracking-tight text-slate-900">{it.t}</p>
        </div>
        {readable
          ? <ChevronDown size={16} className="mt-0.5 flex-shrink-0 text-slate-300" style={{ transform: open ? "rotate(180deg)" : "none", transition: "transform .25s ease" }} />
          : (it.live && <BadgeCheck size={14} style={{ color: EM }} className="mt-0.5 flex-shrink-0" />)}
      </button>

      {/* Inline reader — expands in place */}
      <div style={{ display: "grid", gridTemplateRows: open ? "1fr" : "0fr", transition: "grid-template-rows .26s ease" }}>
        <div className="overflow-hidden">
          <div className="border-t border-slate-100 px-3.5 pb-3.5 pt-3">
            {it.originalTitle && it.originalTitle !== it.t && (
              <p className="mb-2 text-[11px] font-semibold italic leading-snug text-slate-400">“{it.originalTitle}”</p>
            )}
            {it.whatHappened && <p className="text-[12.5px] font-medium leading-relaxed text-slate-600">{it.whatHappened}</p>}
            {it.why && (
              <p className="mt-2 text-[12.5px] font-medium leading-relaxed text-slate-600">
                <span className="font-bold text-slate-800">Why it matters. </span>{it.why}
              </p>
            )}
            {Array.isArray(it.takeaways) && it.takeaways.length > 0 && (
              <ul className="mt-2.5 space-y-1">
                {it.takeaways.map((k, i) => (
                  <li key={i} className="flex gap-1.5 text-[12px] font-semibold leading-snug text-slate-700">
                    <span aria-hidden="true" className="flex-shrink-0" style={{ color: EM_TEXT }}>•</span><span>{k}</span>
                  </li>
                ))}
              </ul>
            )}
            {it.live && onOpen && (
              <button onClick={() => { haptic(); onOpen(it); }}
                className="mt-3 inline-flex items-center gap-1.5 rounded-xl px-3 py-2 text-[12px] font-bold text-white transition active:scale-95" style={{ background: EM }}>
                Open {it.co} <ArrowUpRight size={13} />
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

