const DM_PEOPLE = [
  { id: "scott", name: "Scott Emerson", sub: "CEO · Kingsmen Resources", mono: "SE", c: "#0f766e" },
  { id: "kingsmen", name: "Kingsmen Resources", sub: "Company · TSXV:KNG", mono: "KR", c: "#1e3a8a" },
  { id: "aurum", name: "Aurum Peak Gold", sub: "Company · TSXV:AUP", mono: "AP", c: "#b45309" },
  { id: "sierra", name: "Sierra Argent Mining", sub: "Company · TSXV:AGX", mono: "SA", c: "#0d9488" },
  { id: "cordillera", name: "Cordillera Copper", sub: "Company · TSXV:CUP", mono: "CC", c: "#c2410c" },
  { id: "maria", name: "Maria Velez", sub: "Analyst · Cordia Capital", mono: "MV", c: "#0d9488" },
  { id: "david", name: "David Chen", sub: "Analyst · Northcrest Securities", mono: "DC", c: "#2563eb" },
  { id: "tom", name: "Tom Bradshaw", sub: "Analyst · Granite Equity", mono: "TB", c: "#7c3aed" },
];

// Shared, in-memory DM store so a message sent from anywhere (e.g. a CEO profile)
// shows up on the Messages page too. Simple pub/sub keeps both views in sync.
const dmStore = {
  convos: [],   // fresh app — no conversations until the user starts one (honest empty state)
  listeners: new Set(),
  sub(fn) { this.listeners.add(fn); return () => this.listeners.delete(fn); },
  emit() { this.listeners.forEach((fn) => { try { fn(); } catch (_) {} }); },
  get(id) { return this.convos.find((c) => c.id === id); },
  ensure(p) {
    let c = this.get(p.id);
    if (!c) {
      c = { id: p.id, name: p.name, sub: p.sub, mono: p.mono, c: p.c, when: "now", unread: 0, seed: p.seed ? [...p.seed] : [] };
      this.convos = [c, ...this.convos];
      this.emit();
    }
    return c;
  },
  send(id, text) {
    const c = this.get(id);
    if (!c) return;
    c.seed = [...(c.seed || []), { from: "me", text }];
    c.when = "now";
    c.unread = 0;
    this.convos = [c, ...this.convos.filter((x) => x.id !== id)];
    this.emit();
  },
};

function Avatar({ mono, c, size = 52 }) {
  return (
    <div className="flex-shrink-0 grid place-items-center rounded-full font-extrabold text-white" style={{ width: size, height: size, background: c, fontSize: size * 0.34 }}>
      {mono}
    </div>
  );
}

function MessageThread({ convo, onBack }) {
  const [, setTick] = useState(0);
  const [text, setText] = useState("");
  const endRef = useRef(null);
  // Back the thread with the shared store so anything sent here appears in the
  // Messages inbox too.
  useEffect(() => { dmStore.ensure(convo); return dmStore.sub(() => setTick((t) => t + 1)); }, [convo.id]);
  const stored = dmStore.get(convo.id);
  const msgs = (stored && stored.seed) || convo.seed || [];
  useEffect(() => { if (endRef.current) endRef.current.scrollIntoView({ block: "end" }); }, [msgs.length]);
  const send = () => {
    const t = text.trim();
    if (!t) return;
    haptic();
    dmStore.send(convo.id, t);
    setText("");
  };
  return createPortal(
    <div className="absolute inset-0 z-[95] flex flex-col pp-fade" style={{ background: "#ffffff", paddingTop: "env(safe-area-inset-top, 0px)" }}>
      {/* header */}
      <div className="flex flex-shrink-0 items-center gap-3 border-b border-slate-100 px-3 py-2.5">
        <button onClick={onBack} aria-label="Back" className="grid h-9 w-9 place-items-center rounded-full text-slate-700 transition active:scale-90"><ChevronLeft size={22} /></button>
        <Avatar mono={convo.mono} c={convo.c} size={36} />
        <div className="min-w-0 flex-1">
          <p className="truncate text-[14px] font-bold tracking-tight text-slate-900">{convo.name}</p>
          <p className="truncate text-[11px] font-medium text-slate-400">{convo.sub}</p>
        </div>
      </div>
      {/* messages */}
      <div className="pp-scroll flex-1 space-y-2 overflow-y-auto px-4 py-4" style={{ overscrollBehaviorY: "contain" }}>
        {msgs.map((m, i) => (
          <div key={i} className={"flex " + (m.from === "me" ? "justify-end" : "justify-start")}>
            <div className="max-w-[76%] rounded-2xl px-3.5 py-2 text-[13.5px] leading-snug" style={m.from === "me"
              ? { background: "#0f172a", color: "#fff", borderBottomRightRadius: 6 }
              : { background: "#f1f5f9", color: "#0f172a", borderBottomLeftRadius: 6 }}>
              {m.text}
            </div>
          </div>
        ))}
        <div ref={endRef} />
      </div>
      {/* composer */}
      <div className="flex flex-shrink-0 items-center gap-2 border-t border-slate-100 px-3 py-2.5" style={{ paddingBottom: "calc(10px + env(safe-area-inset-bottom, 0px))" }}>
        <input
          value={text}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={(e) => { if (e.key === "Enter") send(); }}
          placeholder="Message…"
          className="h-10 flex-1 rounded-full px-4 text-[14px] outline-none"
          style={{ background: "#f1f5f9" }}
        />
        <button onClick={send} disabled={!text.trim()} aria-label="Send" className="grid h-10 w-10 flex-shrink-0 place-items-center rounded-full text-white transition active:scale-90 disabled:opacity-40" style={{ background: "#0f172a" }}>
          <Send size={17} strokeWidth={2.2} />
        </button>
      </div>
    </div>,
    ppFrameEl || document.body
  );
}

function MessagesScreen() {
  const [open, setOpen] = useState(null);      // active conversation
  const [composing, setComposing] = useState(false);
  const [query, setQuery] = useState("");
  const [, setTick] = useState(0);
  useEffect(() => dmStore.sub(() => setTick((t) => t + 1)), []);

  if (open) return <MessageThread convo={open} onBack={() => setOpen(null)} />;

  // New-message picker.
  if (composing) {
    const q = query.trim().toLowerCase();
    // Message real published companies, not mock people.
    const roster = DIRECTORY.map((c) => ({ id: c.slug, name: c.name, sub: c.ticker || c.commodity || "", mono: c.mono, c: c.c, logo: c.logo }));
    const people = q ? roster.filter((p) => (p.name + " " + p.sub).toLowerCase().includes(q)) : roster;
    return (
      <div className="flex h-full flex-col" style={{ background: "#ffffff" }}>
        <div className="flex flex-shrink-0 items-center gap-3 border-b border-slate-100 px-3 py-2.5">
          <button onClick={() => { setComposing(false); setQuery(""); }} aria-label="Back" className="grid h-9 w-9 place-items-center rounded-full text-slate-700 transition active:scale-90"><ChevronLeft size={22} /></button>
          <p className="text-[15px] font-extrabold tracking-tight text-slate-900">New message</p>
        </div>
        <div className="flex-shrink-0 px-4 pb-2 pt-3">
          <div className="flex items-center gap-2 rounded-full px-3.5" style={{ background: "#f1f5f9", height: 40 }}>
            <Search size={16} className="text-slate-400" />
            <input autoFocus value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search people & companies" className="h-full flex-1 bg-transparent text-[14px] outline-none" />
          </div>
        </div>
        <div className="pp-scroll flex-1 overflow-y-auto px-2 pb-24">
          {people.map((p) => (
            <button key={p.id} onClick={() => { setComposing(false); setQuery(""); setOpen({ ...p, seed: [] }); }} className="flex w-full items-center gap-3 rounded-xl px-2.5 py-2.5 text-left transition active:bg-slate-50">
              <Avatar mono={p.mono} c={p.c} size={46} />
              <div className="min-w-0 flex-1">
                <p className="truncate text-[14px] font-bold tracking-tight text-slate-900">{p.name}</p>
                <p className="truncate text-[11.5px] font-medium text-slate-400">{p.sub}</p>
              </div>
            </button>
          ))}
          {people.length === 0 && <p className="px-4 py-10 text-center text-[13px] font-medium text-slate-400">No matches for “{query}”.</p>}
        </div>
      </div>
    );
  }

  // Inbox.
  const q = query.trim().toLowerCase();
  const convos = q ? dmStore.convos.filter((c) => (c.name + " " + c.sub).toLowerCase().includes(q)) : dmStore.convos;
  return (
    <div className="flex h-full flex-col" style={{ background: "#ffffff" }}>
      <div className="flex flex-shrink-0 items-center justify-between px-5 pb-2 pt-3">
        <h1 className="text-[24px] font-extrabold leading-none tracking-tight text-slate-900">Messages</h1>
        <button onClick={() => { haptic(); setComposing(true); }} aria-label="New message" className="grid h-9 w-9 place-items-center text-slate-800 transition active:scale-90"><PenSquare size={22} /></button>
      </div>
      <div className="flex-shrink-0 px-4 pb-1 pt-1">
        <div className="flex items-center gap-2 rounded-full px-3.5" style={{ background: "#f1f5f9", height: 40 }}>
          <Search size={16} className="text-slate-400" />
          <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search messages" className="h-full flex-1 bg-transparent text-[14px] outline-none" />
        </div>
      </div>
      <div className="pp-scroll flex-1 overflow-y-auto px-2 pb-24 pt-1">
        {convos.map((c) => (
          <button key={c.id} onClick={() => { haptic(); setOpen(c); }} className="flex w-full items-center gap-3 rounded-xl px-2.5 py-2.5 text-left transition active:bg-slate-50">
            <Avatar mono={c.mono} c={c.c} size={52} />
            <div className="min-w-0 flex-1">
              <div className="flex items-center gap-1.5">
                <p className="truncate text-[14.5px] font-bold tracking-tight text-slate-900">{c.name}</p>
                <span className="ml-auto flex-shrink-0 text-[11px] font-semibold text-slate-300">{c.when}</span>
              </div>
              <div className="mt-0.5 flex items-center gap-2">
                <p className={"truncate text-[12.5px] " + (c.unread ? "font-bold text-slate-700" : "font-medium text-slate-400")}>{(c.seed[c.seed.length - 1] || {}).text}</p>
                {c.unread > 0 && <span className="ml-auto flex-shrink-0 grid h-5 min-w-[20px] place-items-center rounded-full px-1.5 text-[10px] font-extrabold text-white" style={{ background: EM }}>{c.unread}</span>}
              </div>
            </div>
          </button>
        ))}
        {convos.length === 0 && <p className="px-4 py-10 text-center text-[13px] font-medium text-slate-400">No conversations match “{query}”.</p>}
      </div>
    </div>
  );
}

